// A focused reimplementation of argparse.ArgumentParser, covering the parts
// this CLI exercises: required value-taking long options with a type
// converter, the automatic -h/--help action, prefix abbreviation, and
// argparse's exact error text and exit codes.

import { SystemExit } from './exit.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';
import { strRepr } from '../pyrepr.mjs';

// argparse's own test for "looks like a negative number rather than a flag".
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];

    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { action = 'store', type = null, required = false, help = '' } = {}) {
    const longest = optionStrings.filter((s) => s.startsWith('--'));
    const dest = (longest[0] ?? optionStrings[0]).replace(/^-+/, '');

    this.actions.push({
      optionStrings,
      dest,
      action,
      type,
      required,
      help,
      takesValue: action === 'store',
      metavar: dest.toUpperCase(),
    });
  }

  formatUsage() {
    return `${formatUsage(this.prog, this.actions)}\n`;
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** argparse.error(): usage plus one message on stderr, then exit status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Resolve a token that starts with a prefix character.
   *
   * Returns null when argparse would treat the token as a positional (a bare
   * '-', a negative number, or anything containing a space), otherwise an
   * object whose `action` is null for an unrecognized option.
   */
  parseOptional(token) {
    if (!token) return null;
    if (!token.startsWith('-')) return null;

    const exact = this.findByOptionString(token);
    if (exact) return { action: exact, optionString: token, explicitArg: null };

    if (token.length === 1) return null; // a lone '-' is a positional

    if (token.includes('=')) {
      const eq = token.indexOf('=');
      const head = token.slice(0, eq);
      const tail = token.slice(eq + 1);
      const byHead = this.findByOptionString(head);
      if (byHead) return { action: byHead, optionString: head, explicitArg: tail };
    }

    const tuples = this.optionTuples(token);
    if (tuples.length > 1) {
      const names = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // no numeric-looking options here
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitArg: null };
  }

  findByOptionString(name) {
    return this.actions.find((a) => a.optionStrings.includes(name)) ?? null;
  }

  /** Abbreviation matching for long options, e.g. '--he' -> '--help'. */
  optionTuples(token) {
    const results = [];

    if (token.startsWith('--')) {
      let prefix = token;
      let explicitArg = null;
      if (token.includes('=')) {
        const eq = token.indexOf('=');
        prefix = token.slice(0, eq);
        explicitArg = token.slice(eq + 1);
      }
      for (const action of this.actions) {
        for (const optionString of action.optionStrings) {
          if (optionString.startsWith(prefix)) {
            results.push({ action, optionString, explicitArg });
          }
        }
      }
    } else {
      // Single-dash tokens may be a short option with a concatenated value.
      const shortPrefix = token.slice(0, 2);
      const shortExplicit = token.slice(2);
      for (const action of this.actions) {
        for (const optionString of action.optionStrings) {
          if (optionString === shortPrefix) {
            results.push({ action, optionString, explicitArg: shortExplicit || null });
          } else if (optionString.startsWith(token)) {
            results.push({ action, optionString, explicitArg: null });
          }
        }
      }
    }

    return results;
  }

  looksLikeOption(token) {
    return this.parseOptional(token) !== null;
  }

  /**
   * parse_args(). Argument ordering matters: argparse reports missing required
   * options *before* it reports unrecognized ones, so `-a 5 -b 5 -c A` (short
   * flags that do not exist) complains that --a/--b/--c are missing.
   */
  parseArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.takesValue) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (token === '--') {
        // argparse only strips '--' while consuming a positional; with no
        // positionals declared it survives into the leftovers.
        extras.push(...argv.slice(i));
        break;
      }

      const optional = this.parseOptional(token);
      if (optional === null) {
        extras.push(token);
        continue;
      }

      const { action, optionString, explicitArg } = optional;

      if (action === null) {
        extras.push(token);
        continue;
      }

      if (action.action === 'help') {
        process.stdout.write(this.formatHelp());
        throw new SystemExit(0);
      }

      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
      } else if (i + 1 < argv.length && !this.looksLikeOption(argv[i + 1])) {
        raw = argv[i + 1];
        i++;
      } else {
        this.error(`argument ${optionString}: expected one argument`);
      }

      namespace[action.dest] = this.convert(action, optionString, raw);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings[a.optionStrings.length - 1]);

