// CPython interpreter limits that are observable from this program.
//
// Since 3.11, converting between int and str is capped at
// sys.int_max_str_digits (4300 by default) as a denial-of-service guard, and
// the cap applies in BOTH directions:
//
//   * int(text) rejects a literal with more than 4300 digit characters. The
//     count is of digit characters actually present, so leading zeros count
//     and underscores do not; the sign does not either.
//   * str(value) — which print() calls — rejects a value whose decimal form
//     would exceed 4300 digits.
//
// The second one is easy to miss because it fires at print time, after earlier
// print() calls have already emitted their output.

import { PyValueError } from './pyerrors.mjs';

export const INT_MAX_STR_DIGITS = 4300;

const LIMIT_MESSAGE =
  `Exceeds the limit (${INT_MAX_STR_DIGITS} digits) for integer string conversion; ` +
  'use sys.set_int_max_str_digits() to increase the limit';

/** Guard for the str -> int direction, given the number of digit characters. */
export function checkStrToIntDigits(digitCount) {
  if (digitCount > INT_MAX_STR_DIGITS) {
    throw new PyValueError(LIMIT_MESSAGE);
  }
}

/**
 * `str(value)` for an int, enforcing the int -> str direction of the limit.
 * Raises PyValueError exactly where CPython's print() would.
 */
export function intToStr(value) {
  const text = value.toString(10);
  const digitCount = value < 0n ? text.length - 1 : text.length;

  if (digitCount > INT_MAX_STR_DIGITS) {
    throw new PyValueError(LIMIT_MESSAGE);
  }

  return text;
}

