// Output plumbing.
//
// CPython block-buffers stdout when it is not a tty and only discovers a write
// failure at interpreter shutdown, where it is reported as an ignored exception
// and, notably, does NOT change the exit status: piping into `head -1` or
// redirecting to /dev/full still exits 0. Node's streams instead emit an
// 'error' event, and with no listener attached that becomes an unhandled error
// event — the process dies with a JS stack trace and status 1.
//
// Installing a no-op listener restores the original observable behaviour:
// output is truncated, the exit status is untouched, and no crash dump appears.
// The residual difference is that CPython also prints its "Exception ignored
// in: <_io.TextIOWrapper name='<stdout>'>" notice to stderr; that text is not
// reproduced here.

let installed = false;

export function installStreamErrorHandling() {
  if (installed) return;
  installed = true;

  process.stdout.on('error', () => {});
  process.stderr.on('error', () => {});
}

function write(stream, text) {
  try {
    stream.write(text);
  } catch {
    // A synchronous EPIPE/ENOSPC is swallowed for the same reason.
  }
}

export function writeStdout(text) {
  write(process.stdout, text);
}

export function writeStderr(text) {
  write(process.stderr, text);
}

