// Port of test14.py.
//
//   1  import argparse
//   2  import base58
//   3
//   4  parser = argparse.ArgumentParser()
//   5  parser.add_argument('--a', type=int, required=True)
//   6  parser.add_argument('--b', type=int, required=True)
//   7  parser.add_argument('--c', type=str, required=True)
//   8  args = parser.parse_args()
//   9
//  10  encoded_int1 = base58.b58encode_int(args.a)
//  11  encoded_int2 = base58.b58encode_int(args.b)
//  12  decoded_int = base58.b58decode_int(args.c)
//  13  print(encoded_int1)
//  14  print(encoded_int2)
//  15  print(decoded_int)
//
// Both integers are encoded before the string is decoded, so a bad --c leaves
// stdout completely empty — nothing is printed until all three values exist.
// Line 15 can fail on its own, though: rendering a very large integer trips
// sys.int_max_str_digits, and by then lines 13 and 14 have already been written.

import { basename } from 'node:path';

import { ArgumentParser, SystemExit, types } from './lib/argparse/index.mjs';
import * as base58 from './lib/base58/index.mjs';
import { PyError } from './lib/pyerrors.mjs';
import { pyPrint } from './lib/pyprint.mjs';
import { installStreamErrorHandling } from './lib/pystdio.mjs';
import { writeTraceback } from './lib/pytraceback.mjs';

// argparse defaults prog to basename(sys.argv[0]); the Node equivalent is the
// script path in argv[1].
const PROG = basename(process.argv[1] ?? 'test14.mjs');

// Statements that can raise, with the traceback location CPython reports. The
// column span for line 12 is the one baked into the compiled code object,
// covering `base58.b58decode_int(args.c)`. Line 15 has no span: its caret would
// underline the whole statement, which CPython renders without a caret line.
const DECODE_SITE = { line: 12, colStart: 14, colEnd: 42 };
const PRINT_SITE = { line: 15 };

/** Run one Python statement, tagging any exception with its source location. */
function at(callSite, statement) {
  try {
    return statement();
  } catch (error) {
    if (error instanceof PyError && error.callSite === undefined) {
      error.callSite = callSite;
    }
    throw error;
  }
}

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: types.int, required: true });
  parser.addArgument(['--b'], { type: types.int, required: true });
  parser.addArgument(['--c'], { type: types.str, required: true });
  const args = parser.parseArgs(argv);

  const encodedInt1 = base58.b58encode_int(args.a); // 编码第一个整数
  const encodedInt2 = base58.b58encode_int(args.b); // 编码第二个整数
  const decodedInt = at(DECODE_SITE, () => base58.b58decode_int(args.c)); // 解码为整数

  pyPrint(encodedInt1);
  pyPrint(encodedInt2);
  at(PRINT_SITE, () => pyPrint(decodedInt));
}

installStreamErrorHandling();

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    // argparse already wrote usage/help; returning normally lets Node drain
    // stdout and stderr before the status is applied.
    process.exitCode = error.code;
  } else if (error instanceof PyError) {
    writeTraceback(error, error.callSite ?? DECODE_SITE);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

