// column span for line 12 is the one baked into the compiled code object,
// covering `base58.b58decode_int(args.c)`. Line 15 has no span: its caret would
// underline the whole statement, which CPython renders without a caret line.
const DECODE_SITE = { line: 12, colStart: 14, colEnd: 42 };
const PRINT_SITE = { line: 15 };

/** Run one Python statement, tagging any exception with its source location. */
function at(callSite, statement) {
  try {
    return statement();
  } catch (error) {
    if (error instanceof PyError && error.callSite === undefined) {
      error.callSite = callSite;
    }
    throw error;
  }
}

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: types.int, required: true });
  parser.addArgument(['--b'], { type: types.int, required: true });
  parser.addArgument(['--c'], { type: types.str, required: true });
  const args = parser.parseArgs(argv);

  const encodedInt1 = base58.b58encode_int(args.a); // 编码第一个整数
  const encodedInt2 = base58.b58encode_int(args.b); // 编码第二个整数
  const decodedInt = at(DECODE_SITE, () => base58.b58decode_int(args.c)); // 解码为整数

  pyPrint(encodedInt1);
  pyPrint(encodedInt2);
  at(PRINT_SITE, () => pyPrint(decodedInt));
}

installStreamErrorHandling();

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    // argparse already wrote usage/help; returning normally lets Node drain
    // stdout and stderr before the status is applied.
    process.exitCode = error.code;
  } else if (error instanceof PyError) {
    writeTraceback(error, error.callSite ?? DECODE_SITE);
    process.exitCode = 1;
  } else {
    throw error;
  }
