// A focused reimplementation of argparse.ArgumentParser, covering the parts
// this CLI exercises: required value-taking long options with a type
// converter, the automatic -h/--help action, prefix abbreviation, and
// argparse's exact error text and exit codes.

import { SystemExit } from './exit.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';
import { strRepr } from '../pyrepr.mjs';
import { writeStderr, writeStdout } from '../pystdio.mjs';

// argparse's own test for "looks like a negative number rather than a flag".
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];

    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { action = 'store', type = null, required = false, help = '' } = {}) {
    const longest = optionStrings.filter((s) => s.startsWith('--'));
    const dest = (longest[0] ?? optionStrings[0]).replace(/^-+/, '');

    this.actions.push({
      optionStrings,
      dest,
      action,
      type,
      required,
      help,
      takesValue: action === 'store',
      metavar: dest.toUpperCase(),
    });
  }

  formatUsage() {
    return `${formatUsage(this.prog, this.actions)}\n`;
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** argparse.error(): usage plus one message on stderr, then exit status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Resolve a token that starts with a prefix character.
   *
   * Returns null when argparse would treat the token as a positional (a bare
   * '-', a negative number, or anything containing a space), otherwise an
   * object whose `action` is null for an unrecognized option.
   *
   * `sep` records how a value was attached: '=' for `--opt=value`, '' for a
   * short option with its value concatenated (`-hx`), null when no value was
   * attached. argparse treats those two attachments differently for zero-
   * argument actions, so the distinction has to survive.
   */
  parseOptional(token) {
    if (!token) return null;
    if (!token.startsWith('-')) return null;

    const exact = this.findByOptionString(token);
    if (exact) return { action: exact, optionString: token, sep: null, explicitArg: null };

    if (token.length === 1) return null; // a lone '-' is a positional

    if (token.includes('=')) {
      const eq = token.indexOf('=');
      const head = token.slice(0, eq);
      const tail = token.slice(eq + 1);
      const byHead = this.findByOptionString(head);
      if (byHead) return { action: byHead, optionString: head, sep: '=', explicitArg: tail };
    }

    const tuples = this.optionTuples(token);
    if (tuples.length > 1) {
      const names = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // no numeric-looking options here
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, sep: null, explicitArg: null };
  }

  findByOptionString(name) {
    return this.actions.find((a) => a.optionStrings.includes(name)) ?? null;
  }

  /**
   * argparse._get_action_name(): every option string joined with '/'. This is
   * the spelling that appears in "argument -h/--help: ..." messages, and it is
   * independent of which spelling the user actually typed.
   */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  /** Abbreviation matching for long options, e.g. '--he' -> '--help'. */
  optionTuples(token) {
    const results = [];

    if (token.startsWith('--')) {
      let prefix = token;
      let explicitArg = null;
      if (token.includes('=')) {
        const eq = token.indexOf('=');
        prefix = token.slice(0, eq);
        explicitArg = token.slice(eq + 1);
      }
      for (const action of this.actions) {
        for (const optionString of action.optionStrings) {
          if (optionString.startsWith(prefix)) {
            results.push({ action, optionString, sep: explicitArg === null ? null : '=', explicitArg });
          }
        }
      }
    } else {
      // Single-dash tokens may be a short option with a concatenated value.
      const shortPrefix = token.slice(0, 2);
      const shortExplicit = token.slice(2);
      for (const action of this.actions) {
        for (const optionString of action.optionStrings) {
          if (optionString === shortPrefix) {
            results.push({
              action,
              optionString,
              sep: shortExplicit ? '' : null,
              explicitArg: shortExplicit || null,
            });
          } else if (optionString.startsWith(token)) {
            results.push({ action, optionString, sep: null, explicitArg: null });
          }
        }
      }
    }

    return results;
  }

  /**
   * parse_args().
   *
   * argparse works in two passes, and the split is observable. It first
   * classifies every token to build its option-string index, then consumes the
   * result. Ambiguous abbreviations are therefore reported during
   * classification, before any value is converted: `--a bogus --=5` complains
   * about the ambiguous `--=5`, not about `bogus`.
   *
   * Ordering matters at the end too — missing required options are reported
   * before unrecognized ones, so `-a 5 -b 5 -c A` (short flags that do not
   * exist) complains that --a/--b/--c are missing.
   */
  parseArgs(argv) {
    const classified = this.classify(argv);

    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.takesValue) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];

    for (let i = 0; i < classified.length; i++) {
      const entry = classified[i];

      // Positionals and unrecognized options both become leftovers; this
      // parser declares no positional arguments.
      if (entry.kind === 'positional' || entry.action === null) {
        extras.push(entry.token);
        continue;
      }

      const { action, sep, explicitArg } = entry;

      if (action.action === 'help') {
        // A zero-argument action rejects a value attached with '=' rather than
        // discarding it, so `--help=x` and `-h=x` are errors. A value merely
        // concatenated to a short option (`-hx`) instead means bundled short
        // options, which argparse resolves by taking this action and then
        // re-dispatching '-' + the remainder. Help exits immediately, so that
        // continuation is unreachable here.
        if (explicitArg !== null && sep === '=') {
          this.error(
            `argument ${ArgumentParser.actionName(action)}: ignored explicit argument ${strRepr(explicitArg)}`,
          );
        }
        writeStdout(this.formatHelp());
        throw new SystemExit(0);
      }

      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
      } else if (i + 1 < classified.length && classified[i + 1].kind === 'positional') {
        raw = classified[i + 1].token;
        i++;
      } else {
        this.error(`argument ${ArgumentParser.actionName(action)}: expected one argument`);
      }

      namespace[action.dest] = this.convert(action, raw);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => ArgumentParser.actionName(a));

    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }

  /**
   * Pass one: label every token as an option or a positional. A bare '--' ends
   * option parsing, and argparse only strips it while consuming a positional —
   * with none declared, it and everything after it survive as leftovers.
   */
  classify(argv) {
    const entries = [];
    let optionsEnded = false;

    for (const token of argv) {
      if (optionsEnded || token === '--') {
        optionsEnded = true;
        entries.push({ kind: 'positional', token });
        continue;
      }

      const optional = this.parseOptional(token);
      entries.push(
        optional === null ? { kind: 'positional', token } : { kind: 'optional', token, ...optional },
      );
    }

    return entries;
  }

  convert(action, raw) {
    if (!action.type) return raw;

    try {
      return action.type.fn(raw);
    } catch {
      // argparse quotes the *original* text with repr(), so escapes survive.
      this.error(
        `argument ${ArgumentParser.actionName(action)}: invalid ${action.type.name} value: ${strRepr(raw)}`,
      );
    }
  }
}

